from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data, sequence_first=False, original_tax=False):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if sequence_first:
            rank = (sequence, event.get("revision", 0), position)
        else:
            rank = (event.get("revision", 0), position)
        if event_id not in chosen or rank > chosen[event_id][0]:
            chosen[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        base = raw if original_tax else net
        tax = _round(base * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = [[-1] + [row["version"] for row in packages[name]]
               for name in names]
    best_vector = None
    best_installation = None

    for vector in product(*domains):
        installed = {name: version for name, version in zip(names, vector)
                     if version != -1}
        if any(version in blocked.get(name, []) or
               (name in pins and pins[name] != version)
               for name, version in installed.items()):
            continue

        rows = {}
        for name, version in installed.items():
            rows[name] = next(row for row in packages[name]
                              if row["version"] == version)

        constraints = {name: [tuple(bounds)]
                       for name, bounds in data["roots"].items()}
        edges = {name: [] for name in installed}
        required = set(data["roots"])
        pending = list(required)
        valid = True
        while pending and valid:
            name = pending.pop()
            if name not in installed:
                valid = False
                break
            row = rows[name]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                edges[name].append(other)
                constraints.setdefault(other, []).append((dep["min"], dep["max"]))
                if other not in required:
                    required.add(other)
                    pending.append(other)
        if not valid or set(installed) != required:
            continue
        for name, ranges in constraints.items():
            version = installed.get(name)
            if version is None or any(not low <= version <= high
                                      for low, high in ranges):
                valid = False
                break
        if not valid:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            state[name] = 2
            return True

        if not all(visit(name) for name in installed):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_installation = installed

    if best_vector is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for chosen in combinations(options, k):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(sum(job["start"] <= time < job["end"] for job in chosen) > 2
               for time in (job["start"] for job in chosen)):
            continue
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial_state = (source, initial_mask, data["coupons"])
    distances = {initial_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, coupons - 1))
            next_node = edge["v"]
            next_mask = mask | bit_for.get(next_node, 0)
            for duration, remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: _ledger(data, False, False),
    "component_02": lambda data: _ledger(data, True, False),
    "component_03": lambda data: _ledger(data, False, True),
    "component_04": lambda data: _ledger(data, True, True),
    "component_05": lambda data: _ledger(data, False, False),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}
